import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 허용 인증기기 수 설정값의 출처가 입력에 없어 임직원당 3대로 둔다.
const ALLOWED_DEVICE_COUNT = 3;

@Controller('api/v1')
export class FnSfr03704Controller {
  @Post('/auth-devices')
  @HttpCode(200)
  async createAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const identifier = data['deviceIdentifier'];
    if (typeof identifier !== 'string' || identifier.trim() === '' || identifier.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인증기기 식별값을 200자 이내로 입력해 주세요.');
    }
    const rawName = data['deviceName'];
    if (rawName !== undefined && rawName !== null && typeof rawName !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '기기 명칭 형식이 올바르지 않습니다.');
    }
    if (typeof rawName === 'string' && rawName.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '기기 명칭은 100자 이내로 입력해 주세요.');
    }
    // 가정: 기기 명칭을 비우면 식별값 앞 100자를 명칭으로 저장한다 (컬럼이 NOT NULL).
    const deviceName = typeof rawName === 'string' && rawName.trim() !== ''
      ? rawName
      : identifier.slice(0, 100);
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '임직원 정보를 찾을 수 없습니다.');
      }
      // 이미 신청 또는 승인된 기기는 중복 등록으로 본다.
      const duplicated = await db.query(
        "SELECT auth_device_id AS \"authDeviceId\" FROM auth_device WHERE device_identifier = :identifier AND status IN ('신청', '승인')",
        { identifier },
      );
      if (duplicated.length > 0) {
        throw new ApiError(409, 'AUTH_DEVICE_DUPLICATED', '이미 등록된 인증기기입니다.');
      }
      // 신청·승인 상태의 기기를 임직원의 등록 수로 센다.
      const counted = await db.query(
        "SELECT COUNT(*) AS \"cnt\" FROM auth_device WHERE employee_id = CAST(:userId AS bigint) AND status IN ('신청', '승인')",
        { userId: user.id },
      );
      const count = Number(counted[0]['cnt']);
      if (count >= ALLOWED_DEVICE_COUNT) {
        throw new ApiError(422, 'ALLOWED_DEVICE_COUNT_EXCEEDED', '허용 인증기기 수를 초과하여 신청할 수 없습니다.');
      }
      const rows = await db.query(
        "INSERT INTO auth_device (employee_id, device_identifier, device_name, status, created_at, updated_at) VALUES (CAST(:userId AS bigint), :identifier, :deviceName, '신청', now(), now()) RETURNING auth_device_id AS \"authDeviceId\", status AS \"status\"",
        { userId: user.id, identifier, deviceName },
      );
      return rows[0];
    });
  }
}

