import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03704Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [deviceIdentifier, setDeviceIdentifier] = useState('');
  const [deviceName, setDeviceName] = useState('');

  const openDrawer = () => {
    setDeviceIdentifier('');
    setDeviceName('');
    setOpen(true);
  };

  const submit = async () => {
    if (deviceIdentifier.trim() === '') {
      throw new Error('인증기기 식별값을 입력해 주세요.');
    }
    const result = await call('POST', '/auth-devices', role, {
      deviceIdentifier,
      deviceName,
    });
    setRows([
      { ...result, deviceIdentifier, deviceName },
      ...rows,
    ]);
    setOpen(false);
    notify('인증기기 등록을 신청했습니다.');
  };

  const waiting = rows.filter((r) => r.status === '신청').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles
          items={[
            ['이번 신청', rows.length],
            ['승인 대기', waiting],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>신청 내역</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openDrawer}>
            인증기기 등록 신청
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'authDeviceId', label: '인증기기 ID' },
            { key: 'deviceIdentifier', label: '인증기기 식별값' },
            { key: 'deviceName', label: '기기 명칭' },
            {
              key: 'status',
              label: '상태',
              render: (row) => <Badge value={row.status} />,
            },
          ]}
          rows={rows}
          empty="이 화면에서 신청한 인증기기가 없습니다."
        />
      </section>
      {open && (
        <Drawer title="인증기기 등록 신청" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="신청">
            <Field label="인증기기 식별값" required wide>
              <TextInput value={deviceIdentifier} onChange={setDeviceIdentifier} />
            </Field>
            <Field label="기기 명칭" wide>
              <TextInput value={deviceName} onChange={setDeviceName} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
